CREATE TYPE "PaymentStatus" AS ENUM ('PENDING','CONFIRMED','REJECTED');
CREATE TABLE "Admin" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Lot" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"price" DECIMAL(10,2) NOT NULL,"startDate" TIMESTAMP(3) NOT NULL,"endDate" TIMESTAMP(3) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"displayOrder" INTEGER NOT NULL UNIQUE,"quantityLimit" INTEGER,"quantitySold" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Registration" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"phone" TEXT NOT NULL,"email" TEXT NOT NULL,"graduatedFromSchool" BOOLEAN NOT NULL,"graduationYear" INTEGER,"lotId" TEXT NOT NULL,"amountPaid" DECIMAL(10,2) NOT NULL,"paymentStatus" "PaymentStatus" NOT NULL DEFAULT 'PENDING',"proofFileKey" TEXT NOT NULL UNIQUE,"proofOriginalName" TEXT NOT NULL,"proofMimeType" TEXT NOT NULL,"proofSize" INTEGER NOT NULL,"submittedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"idempotencyKey" TEXT UNIQUE, CONSTRAINT "Registration_lotId_fkey" FOREIGN KEY ("lotId") REFERENCES "Lot"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "AdminAction" ("id" TEXT PRIMARY KEY,"adminId" TEXT NOT NULL,"registrationId" TEXT NOT NULL,"action" TEXT NOT NULL,"previousStatus" "PaymentStatus","newStatus" "PaymentStatus","createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AdminAction_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "Admin"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "AdminAction_registrationId_fkey" FOREIGN KEY ("registrationId") REFERENCES "Registration"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
